local SkipRayCastingCheckNodeType2Func = {
    [SpecialEventNodeType.Toggle]     = function (toggle)
        toggle.isOn = true
    end,
    [SpecialEventNodeType.QuickTap]   = function (quickTap)
        quickTap.onTap:Invoke()
    end,
    [SpecialEventNodeType.QuickTouch] = function (quickTouch)
        quickTouch.onTouch:Invoke()
    end,
    [SpecialEventNodeType.TabButton]  = function (tabButton)
        local tabGroup = tabButton.gameObject:GetComponentInParent(TabGroupType)
        tabGroup:OnTabChanged(tabButton, true)
    end,
}

