---@class UISystemGuideEventNode
local UISystemGuideEventNode = Class("UISystemGuideEventNode")

function UISystemGuideEventNode:__init()
    self:ClearSkipRayCastingCheckNode()
end

function UISystemGuideEventNode:__delete()
    self.context = nil
    self:ClearSkipRayCastingCheckNode()
end

function UISystemGuideEventNode:ClearSkipRayCastingCheckNode()
    self.isSkipRayCastingCheck = nil
    self.toggleList     = nil
    self.quickTapList   = nil
    self.tabButtonList  = nil
    self.quickTouchList = nil
end


---Execute
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuideEventNode:Execute(moduleStepVo)
    local eventInfoStr = moduleStepVo.eventInfo
    if string.isEmpty(eventInfoStr) then return end
    local context = self.context
    
    local eventNodeList = {}
    local eventInfoList = ParseStringByLevel(SplitFlagLevel.Level1, eventInfoStr)
    for i, eventNodeParamsStr in ipairs(eventInfoList) do
        local eventNodeType, eventParams = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, eventNodeParamsStr))
        local eventNode = self:ParseEventNode(eventNodeType, eventParams)
        if not isNull(eventNode) then
            table.insert(eventNodeList, eventNode)
        end

    end

    --- 无事件节点不处理后续
    if next(eventNodeList) == nil then
        return
    end
    context:SetEventNodeList(eventNodeList)

    local eventBehaviorStr = moduleStepVo.eventBehavior
    --- eventBehaviorStr: 1#2:x ; 1#2:x ; 1#2:x
    if string.isEmpty(eventBehaviorStr) then return end
    
    local eventBehaviorList = ParseStringByLevel(SplitFlagLevel.Level1, eventBehaviorStr)
    for i, eventBehaviorParamsStr in ipairs(eventBehaviorList) do
        local eventBehaviorParamsList = ParseStringByLevel(SplitFlagLevel.Level2, eventBehaviorParamsStr)
        --print("eventBehaviorParamsStr", eventBehaviorParamsStr)
        for index, oneEventBehaviorParams in ipairs(eventBehaviorParamsList) do
            local list = ParseStringByLevel(SplitFlagLevel.Level3, oneEventBehaviorParams)
            --print(table.toString(list))
            --local eventBehaviorType, eventBehaviorParams = list[1], list[2]
            local eventBehaviorType, eventBehaviorParams = SafeUnpack(list)
            self:OpenEventNodeBehavior(eventBehaviorType, eventBehaviorParams, i, context)
        end

        --local eventBehaviorType, eventBehaviorParams = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, eventBehaviorParamsStr))
        --self:OpenEventNodeBehavior(eventBehaviorType, eventBehaviorParams, i, context)
    end
end

function UISystemGuideEventNode:ExecuteEvent(index)
    if not self.isSkipRayCastingCheck then return end
    for specialNodeType, config in ipairs(SkipRayCastingCheckNodeConfig) do
        local name = SafeUnpack(config)
        if self[name] then
            local func = SkipRayCastingCheckNodeType2Func[specialNodeType]
            if func then
                func(self[name][index + 1])
            end
        end
    end
    self:ClearSkipRayCastingCheckNode()
end

