function UISystemGuideEventNode:ParseEventNode(eventNodeType, eventParams)
    local eventType = checkNumber(eventNodeType)

    local node
    if eventType == ActionType.UI then
        node = self:HandleEventTypeUI(eventParams)

    elseif eventType == ActionType.UIList then
        node = self:HandleEventTypeUIList(eventParams)

    elseif eventType == ActionType.ThreeDimensionalObject then
        node = self:HandleEventTypeThreeDimensionalObject(eventParams)

    end

    return node
end

function UISystemGuideEventNode:HandleEventTypeUI(eventParams)
    local context = self.context
    --GuideUtils.SplitFlagLevel()
    ---1,UIHomeView/Root/BottomPanel/RightGroup/BtnCultivate
    local regionParams = ParseStringByLevel(SplitFlagLevel.Level3, eventParams)
    local nodePath     = SafeUnpack(regionParams)
    local node         = GuideUtils.GetNode(nodePath)
    -- context:AddCornersByRectTransform(node.transform)

    --- 焦点检查 理论上应该挪到 OpenEventNodeBehavior
    context:FreshFocusCheckShowState(true)
    context:FreshFullScreenTouchRegionShowState(false)
    return node
end

function UISystemGuideEventNode:HandleEventTypeUIList(eventParams)
    local context = self.context
    ---2,UIHomeView/Root/BottomPanel/RightGroup/BtnDrawCard:1:1:-4.00001:-56.50006:158:21:0.5:0.5:0.5:0.5
    --local params = parse_strings(eventParams, ":")
    local params = ParseStringByLevel(SplitFlagLevel.Level3, eventParams)
    local nodePath, nodeIndex, path, isMove, _, _, subCellIndex = SafeUnpack(params)
    local node = GuideUtils.GetListCell(nodePath, nodeIndex, path, checkNumber(isMove) == 1, subCellIndex)
    -- context:AddCornersByRectTransform(node.transform)
    --- 检查是否为空
    if isNull(node) then return end

    --- 焦点检查 理论上应该挪到 OpenEventNodeBehavior
    context:FreshFocusCheckShowState(true)
    context:FreshFullScreenTouchRegionShowState(false)
    return node
end

function UISystemGuideEventNode:HandleEventTypeThreeDimensionalObject(eventParams)
    local context = self.context
    context:SetEventNodeIs3D(true)
    return GuideUtils.GetNode(eventParams, 1)
end

