function UISystemGuideEventNode:OpenEventNodeBehavior(eventBehaviorType, eventBehaviorParams, index)
    eventBehaviorType = checkNumber(eventBehaviorType)
    if eventBehaviorType == EventNodeBehaviorType.OpenCheckClickRegion then
        self:HandleTypeOpenCheckClickRegion()

    elseif eventBehaviorType == EventNodeBehaviorType.SpecifyEventNode then
        self:HandleTypeSpecifyEventNode(index)

    elseif eventBehaviorType == EventNodeBehaviorType.SkipRayCastingCheck then
        self:HandleTypeSkipRayCastingCheck(eventBehaviorParams, index)

    end

end

function UISystemGuideEventNode:HandleTypeOpenCheckClickRegion()
    self.context:UpdateCheckRayCastState(true)

end

function UISystemGuideEventNode:HandleTypeSpecifyEventNode(index)
    local context = self.context
    local eventNodeList = context:GetEventNodeList()
    local go = eventNodeList[index].gameObject
    context:AddSpecifyGameObject(go)
    context:SetIsSpecifyEventNode(true)
end

function UISystemGuideEventNode:HandleTypeSkipRayCastingCheck(eventBehaviorParams, index)
    --print("eventBehaviorParams, index", eventBehaviorParams, index)
    local t    = SkipRayCastingCheckNodeConfig
    local info = t[checkNumber(eventBehaviorParams)]
    if info == nil then
        printError("guide---------------->>>> error 动作效果类型 跳过射线检测 未知参数类型 = %s, 节点下标 = %s", eventBehaviorParams, index)
        return
    end
    local context       = self.context
    local eventNodeList = context:GetEventNodeList()
    local eventNode     = eventNodeList[index]
    local name, componentType = SafeUnpack(info)
    self[name] = self[name] or {}
    self[name][index] = KTool.GetComponent(eventNode.gameObject, componentType)
    self.isSkipRayCastingCheck = true
    context:UpdateSkipRayCastCheckState(true)
    
